+		clocks = <&wm8960_mclk>;
+		clock-names = "mclk";
+		AVDD-supply = <&vdc_3v3>;
+		SPKVDD1-supply = <&vdc_5v>;
+		SPKVDD2-supply = <&vdc_5v>;
+		#sound-dai-cells = <0>;
+	};
+};
+
+&lpass_tlmm {
+	lpi_i2s1_active: lpi-i2s1-active-state {
+		clk-pins {
+			pins = "gpio6";
+			function = "i2s1_clk";
+			drive-strength = <8>;
+			bias-disable;
+		};
+
+		ws-pins {
+			pins = "gpio7";
+			function = "i2s1_ws";
+			drive-strength = <8>;
+			bias-disable;
+		};
+
+		data-pins {
+			pins = "gpio8", "gpio9";
+			function = "i2s1_data";
+			drive-strength = <8>;
+			bias-disable;
+		};
+	};
+};
+
+&sound {
+	pinctrl-0 = <&quad_mi2s_active>, <&quad_mclk_active>, <&lpi_i2s4_active>,
+		    <&lpi_i2s1_active>;
+
+	i2s1-playback-dai-link {
+		link-name = "JHAT Analog Playback";
+
+		codec {
+			sound-dai = <&wm8960>;
+		};
+
+		cpu {
+			sound-dai = <&q6apmbedai LPI_MI2S_RX_1>;
+		};
+
+		platform {
+			sound-dai = <&q6apm>;
+		};
+	};
+
+	i2s1-capture-dai-link {
+		link-name = "JHAT Analog Capture";
+
+		codec {
+			sound-dai = <&wm8960>;
+		};
+
+		cpu {
+			sound-dai = <&q6apmbedai LPI_MI2S_TX_1>;
+		};
+
+		platform {
+			sound-dai = <&q6apm>;
+		};
+	};
+};
