+	/* Still fail if CKTX0_EN was not disabled, but at least AUX is off */
+	if (ret_cktx) {
+		dev_err(&phy->dev, "Could not disable CKTX0: %d\n", ret_cktx);
+		return ret_cktx;
+	}
